def _validate_braces(self):
    """Ensure all braces in the format string are properly matched."""
    depth = 0
    i = 0
    fmt = self._format
    while i < len(fmt):
        if fmt[i] == '{':
            if i + 1 < len(fmt) and fmt[i + 1] == '{':
                i += 2
                continue
            depth += 1
        elif fmt[i] == '}':
            if i + 1 < len(fmt) and fmt[i + 1] == '}':
                i += 2
                continue
            depth -= 1
            if depth < 0:
                raise ValueError('unmatched closing brace')
        i += 1
    if depth != 0:
